const paths={chevron:'m6 9 6 6 6-6',arrow:'M4 12h16m-6-6 6 6-6 6',external:'M14 4h6v6m0-6L10 14M9 4H4v16h16v-5',up:'M12 20V4m-6 6 6-6 6 6',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',folder:'M3 7V4h6l3 3h9v13H3z',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-2-15-4 18',check:'m5 12 4 4L19 6',file:'M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h5',layers:'m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5',book:'M12 5v16M3 3c4-1 6 0 9 2 3-2 5-3 9-2v16c-4-1-6 0-9 2-3-2-5-3-9-2z',type:'M4 4h16M12 4v16M8 20h8',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 8l-3 5-5 3 3-5z',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 3h.01',sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',moon:'M20 15a8 8 0 0 1-11-11A8 8 0 1 0 20 15Z'};
function icons(){document.querySelectorAll('[data-icon]').forEach(svg=>{svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');svg.innerHTML='<path d="'+paths[svg.dataset.icon]+'"/>';});}icons();
const editions={one:{name:'Vibe One',kicker:"FOR THE IDEAS YOU CAN'T LEAVE ALONE",heading:'A little structure.<br><em>A lot of possibility.</em>',description:'Bring the idea you keep coming back to. Shape a clear brief, build with Codex, and make the next version your own.',sampleName:'A home for a new idea',sampleHeading:'From a first thought<br>to a working first version.',sampleDescription:'A simple product brief. The files it needs. Room to try something, see it working, and keep going.',workspace:'The same creative foundation, from the first brief to the working project. Each part has a purpose, and your next step is always close.',workflow:'Describe the person, the problem, and the first useful thing your product should do.',startHeading:'One thought.<br><em>Room to make it real.</em>',startDescription:'Write the first version of your idea. Create the project in your selected offering, then take it into Practice.',placeholder:'A thoughtful website for my next idea…'},law:{name:'Vibe Law',kicker:'FOR THE NEXT GENERATION OF LEGAL WORK',heading:'Legal minds.<br><em>New possibilities.</em>',description:'For law students, lawyers, and teams with better ways of working in mind. Bring your legal technology idea into a focused space to build and explore.',sampleName:'A better legal workflow',sampleHeading:'A considered brief.<br>A more useful legal tool.',sampleDescription:'A research workflow. A matter tracker. A first legal technology project, with its context kept close and its next step clear.',workspace:'A focused starting point for legal technology, with the same connected account, brief, design and coding tools. Keep research and project context together.',workflow:'Describe the legal workflow, who it serves, and a small, testable first milestone.',startHeading:'A better workflow.<br><em>Start with the first idea.</em>',startDescription:'Describe the legal technology project you want to explore. Create it under Vibe Law, then take the next step in Practice.',placeholder:'A research workspace for my legal studies…'}};
let edition='one';
function setEdition(next,updateUrl=true){edition=Object.hasOwn(editions,next)?next:'one';const copy=editions[edition];document.body.dataset.edition=edition;document.title=copy.name+' — A little structure. More making.';$('#brand-name').textContent=copy.name;$('#hero-kicker').textContent=copy.kicker;$('#hero-heading').innerHTML=copy.heading;$('#hero-description').textContent=copy.description;$('#preview-edition').textContent=copy.name.toUpperCase();$('#sample-name').textContent=copy.sampleName;$('#sample-heading').innerHTML=copy.sampleHeading;$('#sample-description').textContent=copy.sampleDescription;$('#workspace-description').textContent=copy.workspace;$('#workflow-one').textContent=copy.workflow;$('#start-heading').innerHTML=copy.startHeading;$('#start-description').textContent=copy.startDescription;$('#idea').placeholder=copy.placeholder;$('#form-edition').textContent=copy.name.toUpperCase();$('#idea-status').textContent='Your selected offering: '+copy.name+'.';$('#idea-status').classList.remove('error');document.querySelectorAll('[data-edition]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.edition===edition)));document.querySelectorAll('[data-offering-card]').forEach(card=>card.classList.toggle('selected',card.dataset.offeringCard===edition));document.querySelectorAll('a[href^="/account/"],#demo-plans-link').forEach(link=>{const url=new URL(link.href);url.searchParams.set('edition',edition);link.href=url.pathname+url.search+url.hash;});document.querySelectorAll('.main-nav>details').forEach(menu=>menu.open=false);if(updateUrl){const url=new URL(location.href);if(url.searchParams.get('edition')!==edition){url.searchParams.set('edition',edition);history.pushState({edition},'',url);}}try{localStorage.setItem('vibe-edition',edition);}catch{}}
let savedEdition='one';try{savedEdition=localStorage.getItem('vibe-edition')||'one';}catch{}setEdition(new URLSearchParams(location.search).get('edition')||savedEdition,false);const initialUrl=new URL(location.href);initialUrl.searchParams.set('edition',edition);history.replaceState({edition},'',initialUrl);
document.querySelectorAll('[data-edition]').forEach(button=>button.onclick=()=>setEdition(button.dataset.edition));addEventListener('popstate',()=>setEdition(new URLSearchParams(location.search).get('edition')||'one',false));
function setTheme(theme){document.documentElement.dataset.theme=theme;const dark=theme==='dark';$('#theme').setAttribute('aria-label','Switch to '+(dark?'light':'dark')+' theme');$('#theme').setAttribute('aria-pressed',String(dark));$('#theme svg').dataset.icon=dark?'moon':'sun';icons();try{localStorage.setItem('vibe-frontdoor-theme',theme);}catch{}}
setTheme(document.documentElement.dataset.theme==='dark'?'dark':'light');$('#theme').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
const menus=[...document.querySelectorAll('.main-nav>details')];menus.forEach(menu=>menu.addEventListener('toggle',()=>{if(menu.open)menus.forEach(other=>{if(other!==menu)other.open=false;});}));document.addEventListener('click',event=>{if(!event.target.closest('.main-nav'))menus.forEach(menu=>menu.open=false);});document.addEventListener('keydown',event=>{if(event.key==='Escape'){const focused=document.activeElement;menus.forEach(menu=>{if(menu.open){menu.open=false;if(menu.contains(focused))menu.querySelector('summary').focus();}});}});document.querySelectorAll('.main-nav a').forEach(link=>link.addEventListener('click',()=>menus.forEach(menu=>menu.open=false)));
$('#year').textContent=new Date().getFullYear();
$('#idea-form').onsubmit=async event=>{event.preventDefault();const idea=$('#idea').value.trim(),status=$('#idea-status'),button=event.target.querySelector('button[type=submit]');if(!idea){$('#idea').focus();return;}const selectedEdition=edition;button.disabled=true;status.classList.remove('error');status.textContent='Opening your account…';try{await Vibe.require();if(!Vibe.user.access[selectedEdition]){status.classList.add('error');status.innerHTML='Activate '+editions[selectedEdition].name+' in <a href="/account/?edition='+selectedEdition+'#account">Account settings</a> before creating a project in this offering.';return;}status.textContent='Creating your '+editions[selectedEdition].name+' project…';const project=await Vibe.api('/projects',{brief:{name:idea.slice(0,80),goal:idea,edition:selectedEdition}});location.href='/practice/?project='+encodeURIComponent(project.id);}catch(error){status.classList.add('error');status.textContent=error.message.includes('fetch')?'Start the local companion, then open this page through http://127.0.0.1:4173/frontdoor/.':error.message;}finally{button.disabled=false;}};

